SELECT DISTINCT m.* FROM campus_permission_menu m INNER JOIN campus_role_menu rm ON rm.menu_id = m.menu_id AND rm.deleted = 0 INNER JOIN campus_user_role ur ON ur.role_id = rm.role_id AND ur.deleted = 0 INNER JOIN campus_permission_role r ON r.role_id = ur.role_id AND r.status = 1 AND r.deleted = 0 WHERE ur.user_id = #{userId} AND m.deleted = 0 AND m.status = 1
AND m.visible = #{visible}
ORDER BY m.sort_no ASC, m.id ASC

SELECT FROM campus_permission_api WHERE deleted = 0
AND (api_code LIKE CONCAT('%', #{keyword}, '%') OR api_name LIKE CONCAT('%', #{keyword}, '%') OR request_path LIKE CONCAT('%', #{keyword}, '%'))
AND module_name = #{moduleName}
AND status = #{status}
ORDER BY module_name ASC, id ASC

